import copy
from pathlib import Path
import unittest

namespace = {}
exec(compile(Path('allocator.py').read_text(encoding='utf-8'), 'allocator.py', 'exec'), namespace)
allocate = namespace['allocate']

class AllocateTests(unittest.TestCase):
    def test_available_person_instead_of_fixed_A(self):
        self.assertEqual(allocate('周一', {'周一': ['B']}), ['B'])

    def test_first_person_in_alphabetical_order(self):
        self.assertEqual(allocate('周一', {'周一': ['D', 'B', 'C']}), ['B'])

    def test_empty_availability(self):
        self.assertEqual(allocate('周一', {'周一': []}), [])

    def test_requested_day_only(self):
        self.assertEqual(allocate('周二', {'周一': ['A'], '周二': ['C', 'B']}), ['B'])

    def test_A_selected_when_available_and_first(self):
        self.assertEqual(allocate('周一', {'周一': ['C', 'A', 'B']}), ['A'])

    def test_does_not_change_input(self):
        availability = {'周一': ['D', 'B', 'C'], '周二': ['A']}
        before = copy.deepcopy(availability)
        allocate('周一', availability)
        self.assertEqual(availability, before)

    def test_greeting_preserved(self):
        self.assertEqual(namespace['greeting']('Lin'), 'Hello, Lin!')

